stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class script_object
{
public:
  const stringx& get_name() const;
};

class script_executable
{
public:
  const stringx& get_fullname() const;
};

class vm_thread
{
public:
  script_object* get_instance() const;
  script_executable* get_executable() const;
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;

private:
  vm_thread* my_thread;

public:
  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { SP += -n; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

typedef const stringx* vm_str_t;
typedef unsigned int vm_scene_anim_t;

class world_dynamics_system
{
public:
  vm_scene_anim_t play_scene_anim(const stringx& filename, bool reverse = false,
                                  float start_time = 0.0f);
};

extern world_dynamics_system* g_world_ptr;

class slf_play_scene_anim_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_str_t name;
  };

  virtual bool operator()(vm_stack& stack, entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vm_scene_anim_t result = g_world_ptr->play_scene_anim(*parms->name);
    if (!stack.push((char*)&result, sizeof(result)))
      error(stack.get_thread()->get_instance()->get_name() +
            ": stack overflow in " +
            stack.get_thread()->get_executable()->get_fullname());
    return true;
  }
};
